#include <iostream>

class IntCell {
private:
    int value;
public:
    IntCell(int v) : value(v) {}
    int getValue() const { return value; }
    void setValue(int v) { value = v; }
};

int main() {
    // Circle-like primitive member copy (safe)
    IntCell cell1(5);
    IntCell cell2(cell1); // Default copy constructor invoked

    std::cout << "Initial cell1: " << cell1.getValue() << "\n";
    std::cout << "Initial cell2: " << cell2.getValue() << "\n";

    cell1.setValue(10);
    cell2.setValue(20);

    std::cout << "Modified cell1: " << cell1.getValue() << "\n";
    std::cout << "Modified cell2: " << cell2.getValue() << "\n";

    return 0;
}

#include <iostream>
#include <string>

class Course {
private:
    std::string courseName;
    std::string* students;
    int numberOfStudents;
    int capacity;

public:
    Course(const std::string& name, int cap) {
        courseName = name;
        capacity = cap;
        numberOfStudents = 0;
        students = new std::string[capacity];
    }

    ~Course() {
        delete[] students;
    }

    // Custom copy constructor for Deep Copy
    Course(const Course& other) {
        courseName = other.courseName;
        capacity = other.capacity;
        numberOfStudents = other.numberOfStudents;
        students = new std::string[capacity]; // Allocate separate array
        for (int i = 0; i < numberOfStudents; ++i) {
            students[i] = other.students[i];
        }
    }

    void addStudent(const std::string& name) {
        if (numberOfStudents < capacity) {
            students[numberOfStudents++] = name;
        }
    }

    std::string getStudent(int index) const {
        return students[index];
    }
};

int main() {
    Course course1("C++", 10);
    Course course2(course1); // Deep copy constructor invoked

    course1.addStudent("Peter Pan");
    course2.addStudent("Lisa Ma");

    std::cout << "students in course1: " << course1.getStudent(0) << "\n";
    std::cout << "students in course2: " << course2.getStudent(0) << "\n";

    return 0;
}
